package com.animegraph.identity;
import com.animegraph.audit.AuditService;
import com.animegraph.common.ApiException;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class EvidenceImportServiceTest {
    @Test void duplicateJsonKeysAreRejectedBeforePreviewReads(){var repository=mock(EvidenceImportRepository.class);var service=new EvidenceImportService(repository,EvidencePackageTest.JSON,mock(AuditService.class));assertThrows(ApiException.class,()->service.preview("{\"schemaVersion\":1,\"schemaVersion\":1}".getBytes(java.nio.charset.StandardCharsets.UTF_8),1));verifyNoInteractions(repository);}
    static EvidenceImportRepository.State state(EvidencePackage p,Boolean assertion,Boolean evidence,Map<String,Object> batch){var f=p.facts().getFirst();return new EvidenceImportRepository.State("g1",0,List.of("anime:bangumi:328609"),batch,List.of(new EvidenceImportRepository.NodeState(f.source(),true,List.of(328609L)),new EvidenceImportRepository.NodeState(f.target(),true,List.of(328609L))),List.of(new EvidenceImportRepository.FactState(f.uid(),f.evidenceUid(),assertion,evidence)));}
    @Test void previewReadsOnlyAndCommitIsBoundToActorAndFrozenPackage()throws Exception{
        var repository=mock(EvidenceImportRepository.class);var audit=mock(AuditService.class);var root=EvidencePackageTest.input();var p=EvidencePackage.parse(root,EvidencePackageTest.JSON);var before=state(p,null,null,Map.of());when(repository.snapshot(any())).thenReturn(before);when(repository.apply(any(),anyString(),anyLong())).thenReturn(Map.of("uid",p.batchUid(),"status","APPLIED"));var service=new EvidenceImportService(repository,EvidencePackageTest.JSON,audit);
        var preview=service.preview(EvidencePackageTest.JSON.writeValueAsBytes(root),7);assertTrue(preview.canApply());assertEquals("ADD_ASSERTION",preview.changes().getFirst().action());verify(repository,never()).apply(any(),anyString(),anyLong());assertThrows(ApiException.class,()->service.apply(preview.previewId(),8));service.apply(preview.previewId(),7);verify(repository).apply(eq(p),eq(before.hash(EvidencePackageTest.JSON)),eq(7L));
    }
    @Test void revokedBatchEvidenceAndAssertionCannotBeApproved()throws Exception{var repository=mock(EvidenceImportRepository.class);var p=EvidencePackage.parse(EvidencePackageTest.input(),EvidencePackageTest.JSON);for(var state:List.of(state(p,false,true,Map.of()),state(p,true,false,Map.of()),state(p,true,true,Map.of("status","DISABLED","packageHash",p.hash(EvidencePackageTest.JSON))))){when(repository.snapshot(any())).thenReturn(state);var service=new EvidenceImportService(repository,EvidencePackageTest.JSON,mock(AuditService.class));var preview=service.preview(EvidencePackageTest.JSON.writeValueAsBytes(EvidencePackageTest.input()),1);assertFalse(preview.canApply());assertThrows(ApiException.class,()->service.apply(preview.previewId(),1));}verify(repository,never()).apply(any(),anyString(),anyLong());}
    @Test void changedBatchHashAndMissingWorldMembershipBlockImport(){var p=EvidencePackage.parse(EvidencePackageTest.input(),EvidencePackageTest.JSON);assertFalse(state(p,true,true,Map.of("packageHash","different")).blockers(p,p.hash(EvidencePackageTest.JSON)).isEmpty());var bad=new EvidenceImportRepository.State("",0,List.of(),Map.of(),List.of(new EvidenceImportRepository.NodeState(p.facts().getFirst().source(),null,List.of())),List.of());assertTrue(bad.blockers(p,p.hash(EvidencePackageTest.JSON)).size()>=2);}
    @Test void expirySizeAndDisableReasonAreEnforced()throws Exception{var repository=mock(EvidenceImportRepository.class);var p=EvidencePackage.parse(EvidencePackageTest.input(),EvidencePackageTest.JSON);when(repository.snapshot(any())).thenReturn(state(p,null,null,Map.of()));var clock=mock(Clock.class);when(clock.instant()).thenReturn(Instant.EPOCH);var service=new EvidenceImportService(repository,EvidencePackageTest.JSON,mock(AuditService.class),clock);var preview=service.preview(EvidencePackageTest.JSON.writeValueAsBytes(EvidencePackageTest.input()),1);when(clock.instant()).thenReturn(Instant.EPOCH.plusSeconds(601));assertThrows(ApiException.class,()->service.apply(preview.previewId(),1));assertThrows(ApiException.class,()->service.preview(new byte[512*1024+1],1));assertThrows(ApiException.class,()->service.disable("review-1","",1));verify(repository,never()).disable(anyString(),anyString(),anyLong());}
}
